parameters.jsCode:
const item = $('Webhook').first().json;
const body = item.body || item;
const sessionId = String(body.session_id || ('anon-' + Date.now()));
const raw = String(body.text || '').trim().slice(0, 2000);
const language = String(body.language || 'en').toLowerCase();

// Redact PII
const text = raw
  .replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '[EMAIL]')
  .replace(/\b(?:\d[ -]?){13,19}\b/g, '[CARD]')
  .replace(/(?:\+|00)\d[\d\s().\/-]{7,}\d/g, '[PHONE]');

// Safety & Legal Guardrails
const SAFETY = /\b(fire|smoke|burning smell|crash|accident|brakes? fail)\b/i;
const LEGAL = /\b(lawyer|attorney|sue|lawsuit|lemon law)\b/i;
const HUMAN = /(speak|talk)\b.{0,25}\b(human|agent|person)\b/i;
const FRUSTRATION = /\b(useless|terrible|horrible|angry|worst)\b|!{2,}/i;

let hardEscalate = false, escalationCategory = '', escalationReason = '';
let sentiment = 'neutral';

if (SAFETY.test(text)) {
  hardEscalate = true; escalationCategory = 'safety'; escalationReason = 'Safety critical'; sentiment = 'very_negative';
} else if (LEGAL.test(text)) {
  hardEscalate = true; escalationCategory = 'legal'; escalationReason = 'Legal threat'; sentiment = 'negative';
} else if (HUMAN.test(text)) {
  hardEscalate = true; escalationCategory = 'customer_request'; escalationReason = 'Human requested';
} else if (FRUSTRATION.test(text)) {
  sentiment = 'very_negative'; escalationCategory = 'frustration'; escalationReason = 'High frustration';
}

// Session Tracking
const sd = $getWorkflowStaticData('global');
sd.sessions = sd.sessions || {};
const s = sd.sessions[sessionId] = sd.sessions[sessionId] || { turns: 0, transcript: [], started: new Date().toISOString() };
s.turns += 1;
s.transcript.push({ role: 'customer', text, ts: new Date().toISOString() });

return [{ json: { session_id: sessionId, text, language, turn: s.turns, sentiment, hardEscalate, escalationCategory, escalationReason } }];
